:root {
  --bg: #1b1f3b;
  --card: #f4f1de;
  --ink: #2b2d42;
  --accent: #e07a5f;
  --accent-2: #3d405b;
  --good: #81b29a;
  --warn: #f2cc8f;
  --bad: #e07a5f;
  --shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
  --radius: 16px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  font-family: var(--font);
  font-size: 16px;
  color: var(--ink);
}

body {
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 20% 20%, #2e335c, var(--bg) 60%);
}

.card {
  width: min(100%, 420px);
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  border: 4px solid var(--accent-2);
}

h1 {
  margin: 0;
  text-align: center;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
  color: var(--accent-2);
}

.pet-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.pet {
  width: 120px;
  height: 120px;
  display: grid;
  place-items: center;
  transition: transform 0.2s ease;
}

.pet-body {
  position: relative;
  width: 100px;
  height: 100px;
  background: var(--accent);
  border-radius: 12px;
  box-shadow: inset -6px -6px 0 rgba(0, 0, 0, 0.12), 0 6px 0 var(--accent-2);
  transition: background 0.3s ease;
}

.pet-eye {
  position: absolute;
  top: 30px;
  width: 14px;
  height: 18px;
  background: var(--ink);
  border-radius: 4px;
}
.pet-eye.left { left: 22px; }
.pet-eye.right { right: 22px; }

.pet-mouth {
  position: absolute;
  bottom: 26px;
  left: 50%;
  transform: translateX(-50%);
  width: 28px;
  height: 10px;
  border-bottom: 4px solid var(--ink);
  border-radius: 0 0 12px 12px;
  transition: all 0.2s ease;
}

.pet-cheek {
  position: absolute;
  bottom: 34px;
  width: 12px;
  height: 8px;
  background: rgba(224, 122, 95, 0.6);
  border-radius: 50%;
}
.pet-cheek.left { left: 12px; }
.pet-cheek.right { right: 12px; }

.pet.happy .pet-body { background: var(--accent); }
.pet.sad .pet-body { background: #b5838d; }
.pet.sleepy .pet-body { background: var(--accent-2); }
.pet.sleepy .pet-eye { height: 4px; top: 38px; }
.pet.sad .pet-mouth {
  border-bottom: none;
  border-top: 4px solid var(--ink);
  border-radius: 12px 12px 0 0;
}
.pet.happy .pet-mouth { width: 32px; }

.pet.bounce { transform: translateY(-6px) scale(1.03); }

.mood {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 600;
  text-align: center;
  min-height: 1.4em;
  color: var(--accent-2);
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--accent-2);
}

.bar {
  height: 16px;
  background: #d9d4c5;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--accent-2);
}

.bar-fill {
  height: 100%;
  width: 70%;
  border-radius: 6px;
  transition: width 0.35s ease, background 0.35s ease;
}

.bar-fill.hunger { background: var(--good); }
.bar-fill.happiness { background: var(--warn); }
.bar-fill.energy { background: #6d9dc5; }
.bar-fill.low { background: var(--bad); }

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 8px;
  border-radius: 10px;
  border: 3px solid var(--accent-2);
  background: #fff;
  color: var(--accent-2);
  cursor: pointer;
  transition: transform 0.08s ease, background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
  min-height: 48px;
}

.btn:hover {
  background: var(--accent-2);
  color: #fff;
  transform: translateY(-2px);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn:active {
  transform: translateY(1px) scale(0.98);
  box-shadow: inset 0 3px 0 rgba(0, 0, 0, 0.2);
}

.btn.feed { border-color: var(--good); color: #2f6b53; }
.btn.feed:hover { background: var(--good); color: #fff; }

.btn.play { border-color: var(--warn); color: #8a6d1f; }
.btn.play:hover { background: var(--warn); color: var(--ink); }

.btn.sleep { border-color: #6d9dc5; color: #2f5f8a; }
.btn.sleep:hover { background: #6d9dc5; color: #fff; }

@media (max-width: 360px) {
  .card { padding: 16px; gap: 16px; }
  h1 { font-size: 1.4rem; }
  .controls { gap: 8px; }
  .btn { font-size: 0.95rem; padding: 10px 4px; }
}

const state = {
  hunger: 70,
  happiness: 70,
  energy: 70
};

const petEl = document.getElementById('pet');
const moodEl = document.getElementById('mood');

const els = {
  hunger: {
    bar: document.getElementById('hunger-bar'),
    fill: document.getElementById('hunger-fill'),
    value: document.getElementById('hunger-value')
  },
  happiness: {
    bar: document.getElementById('happiness-bar'),
    fill: document.getElementById('happiness-fill'),
    value: document.getElementById('happiness-value')
  },
  energy: {
    bar: document.getElementById('energy-bar'),
    fill: document.getElementById('energy-fill'),
    value: document.getElementById('energy-value')
  }
};

function clamp(n) {
  return Math.max(0, Math.min(100, Math.round(n)));
}

function updateMood() {
  const { hunger, happiness, energy } = state;
  let mood = 'Your pet is happy to see you!';
  let className = 'happy';

  if (hunger < 25) {
    mood = 'Your pet is very hungry...';
    className = 'sad';
  } else if (energy < 25) {
    mood = 'Your pet is sleepy. Zzz...';
    className = 'sleepy';
  } else if (happiness < 25) {
    mood = 'Your pet feels lonely and sad.';
    className = 'sad';
  } else if (hunger < 50 || happiness < 50 || energy < 50) {
    mood = 'Your pet could use some care.';
    className = 'sad';
  } else if (hunger > 80 && happiness > 80 && energy > 80) {
    mood = 'Your pet is absolutely thrilled!';
    className = 'happy';
  }

  moodEl.textContent = mood;
  petEl.className = 'pet ' + className;
}

function render() {
  for (const key of ['hunger', 'happiness', 'energy']) {
    const val = clamp(state[key]);
    const group = els[key];
    group.fill.style.width = val + '%';
    group.value.textContent = val + '%';
    group.bar.setAttribute('aria-valuenow', String(val));
    group.bar.setAttribute('aria-valuetext', val + '%');
    group.fill.classList.toggle('low', val < 25);
  }
  updateMood();
}

function animatePet() {
  petEl.classList.add('bounce');
  window.setTimeout(() => petEl.classList.remove('bounce'), 220);
}

function feed() {
  state.hunger = clamp(state.hunger + 18);
  state.happiness = clamp(state.happiness + 4);
  state.energy = clamp(state.energy + 2);
  render();
  animatePet();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 12);
  state.hunger = clamp(state.hunger - 8);
  render();
  animatePet();
}

function sleep() {
  state.energy = clamp(state.energy + 25);
  state.hunger = clamp(state.hunger - 6);
  state.happiness = clamp(state.happiness - 4);
  render();
  animatePet();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

// Gentle passive decay over time
let tick = 0;
window.setInterval(() => {
  tick += 1;
  if (tick % 3 === 0) {
    state.hunger = clamp(state.hunger - 1);
    state.happiness = clamp(state.happiness - 1);
    state.energy = clamp(state.energy - 1);
    render();
  }
}, 5000);

render();
